/**
 * `${NAME}` expansion for MCP connection credentials, applied when a
 * transport is built instead of when its module is imported.
 *
 * Discovery imports `mcp-connections/*.ts` once, at startup. A hosted
 * deployment has none of its secrets in the environment at that point: the
 * control plane binds them per request and `consumeHostedBoundSecrets` copies
 * them into `process.env` at the top of the turn. A `process.env.TOKEN` read
 * inside `defineConnection` therefore captures an empty value for the life of
 * the process, while a `"Bearer ${TOKEN}"` template stays verbatim on the
 * transport and resolves here, each time a client opens.
 */
import { createHash } from "node:crypto";
/** `${NAME}`, plus the `mcp.json` spelling `${env:NAME}`. */
const ENV_TEMPLATE = /\$\{(?:env:)?([A-Za-z_][A-Za-z0-9_]*)\}/g;
/** Credential-bearing values of a transport: HTTP headers or stdio env. */
function credentials(transport) {
    if ("url" in transport) {
        return transport.headers;
    }
    if ("command" in transport) {
        return transport.env;
    }
    return undefined;
}
function expand(value, env) {
    return value.replace(ENV_TEMPLATE, (_match, name) => env[name] ?? "");
}
/** The same object back when nothing templates, so callers can compare by identity. */
function expandRecord(values, env) {
    if (values === undefined) {
        return undefined;
    }
    const expanded = {};
    let changed = false;
    for (const [key, value] of Object.entries(values)) {
        expanded[key] = expand(value, env);
        changed ||= expanded[key] !== value;
    }
    return changed ? expanded : values;
}
/**
 * Substitute `${NAME}` in the transport's headers (http/sse) or env (stdio)
 * from the environment as it stands now. An unset variable resolves to an
 * empty string, as reading it in the module would have.
 */
export function resolveConnectionEnvTemplates(transport, env = process.env) {
    if ("url" in transport) {
        const headers = expandRecord(transport.headers, env);
        return headers === transport.headers ? transport : { ...transport, headers };
    }
    if ("command" in transport) {
        const spawnEnv = expandRecord(transport.env, env);
        return spawnEnv === transport.env ? transport : { ...transport, env: spawnEnv };
    }
    return transport;
}
/** Variables a transport templates that the environment does not define, in first-seen order. */
export function unresolvedConnectionEnvNames(transport, env = process.env) {
    const missing = new Set();
    for (const value of Object.values(credentials(transport) ?? {})) {
        for (const match of value.matchAll(ENV_TEMPLATE)) {
            const name = match[1];
            if (name !== undefined && env[name] === undefined) {
                missing.add(name);
            }
        }
    }
    return [...missing];
}
/**
 * Identifies the credentials a client would open with right now, so a cached
 * client is recognizable as stale once the environment changes underneath it.
 * Hashed rather than stored, so the cache key is not a second copy of the
 * secret.
 */
export function connectionCredentialsFingerprint(transport, env = process.env) {
    const resolved = credentials(resolveConnectionEnvTemplates(transport, env));
    if (resolved === undefined) {
        return "";
    }
    return createHash("sha256").update(JSON.stringify(resolved)).digest("hex");
}
